package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class PictureSignatureTest {
    static byte[] scene(int seed){byte[] pixels=new byte[128*128];Random random=new Random(seed);int[] blocks=new int[32*32];for(int n=0;n<blocks.length;n++)blocks[n]=35+random.nextInt(185);for(int y=0;y<128;y++)for(int x=0;x<128;x++)pixels[y*128+x]=(byte)blocks[y/4*32+x/4];return pixels;}
    @Test public void originalExactAndDeclaredBrightnessNoiseVariantsMatch(){byte[] source=scene(41),bright=source.clone(),noise=source.clone();Random random=new Random(12);for(int n=0;n<source.length;n++){bright[n]=(byte)((source[n]&255)+8);noise[n]=(byte)((source[n]&255)+random.nextInt(7)-3);}PictureSignature reference=PictureSignature.from(source,128,128,0);assertTrue(reference.matches(PictureSignature.from(source,128,128,0)));assertTrue(reference.matches(PictureSignature.from(bright,128,128,0)));assertTrue(reference.matches(PictureSignature.from(noise,128,128,0)));assertEquals(reference.key(),PictureSignature.from(source,128,128,0).key());}
    @Test public void clearlyDifferentAndQuarterTurnDoNotMatch(){PictureSignature reference=PictureSignature.from(scene(41),128,128,0);assertFalse(reference.matches(PictureSignature.from(scene(93),128,128,0)));assertFalse(reference.matches(PictureSignature.from(scene(41),128,128,90)));assertFalse(reference.matches(PictureSignature.from(scene(41),128,128,180)));assertFalse(reference.matches(PictureSignature.from(scene(41),128,128,270)));}
    @Test public void blankDarkTexturelessAndCorruptFramesAreRejected(){byte[] blank=new byte[128*128];Arrays.fill(blank,(byte)128);assertThrows(IllegalArgumentException.class,()->PictureSignature.from(blank,128,128,0));byte[] dark=scene(41);for(int n=0;n<dark.length;n++)dark[n]=(byte)((dark[n]&255)/12);assertThrows(IllegalArgumentException.class,()->PictureSignature.from(dark,128,128,0));assertThrows(IllegalArgumentException.class,()->PictureSignature.from(new byte[40],128,128,0));assertThrows(IllegalArgumentException.class,()->PictureSignature.from(scene(41),128,128,45));}
    @Test public void rotationMetadataCorrectsActualRotatedPixels(){byte[] original=scene(41),rotated=new byte[original.length];for(int y=0;y<128;y++)for(int x=0;x<128;x++)rotated[x*128+127-y]=original[y*128+x];assertEquals(PictureSignature.from(original,128,128,0).key(),PictureSignature.from(rotated,128,128,270).key());}
    @Test public void descriptorArraysAreDefensivelyCopiedAndValidated(){PictureSignature a=PictureSignature.from(scene(41),128,128,0);int[] histogram=a.histogram.clone(),edges=a.edges.clone();PictureSignature copy=new PictureSignature(a.hash,a.mean,a.contrast,a.gradient,histogram,edges);String key=copy.key();histogram[0]++;edges[0]++;assertEquals(key,copy.key());assertThrows(IllegalArgumentException.class,()->new PictureSignature(a.hash,a.mean,a.contrast,a.gradient,histogram,edges));assertThrows(IllegalArgumentException.class,()->new PictureSignature(a.hash|1,a.mean,a.contrast,a.gradient,a.histogram,a.edges));}
}
